                     "source":  "Luiz Carlos Reátegui-Jesús María",
                     "published_date":  "2026-06-28T08:42:11",
                     "summary":  "𝗤𝘂𝗲𝗿𝗶𝗱𝗼 𝘃𝗲𝗰𝗶𝗻𝗼 𝗷𝗲𝘀𝘂𝘀𝗺𝗮𝗿𝗶𝗮𝗻𝗼 tú eres testigo de nuestra labor social permanente desde el 2023, 2024, 2025, hasta abril de este año 2026 𝗲𝘀𝘁𝘂𝘃𝗶𝗺𝗼𝘀, 𝗲𝘀𝘁𝗮𝗺𝗼𝘀 𝘆 𝗲𝘀𝘁𝗮𝗿𝗲𝗺𝗼𝘀 𝗱𝗲 𝗹𝗮 𝗺𝗮𝗻𝗼 𝗰𝗼𝗻𝘁𝗶𝗴𝗼, 𝗲𝘀𝗰𝘂𝗰𝗵𝗮́𝗻𝗱𝗼𝘁𝗲, 𝗺𝗶𝗿𝗮́𝗻𝗱𝗼𝘁𝗲 𝗮 𝗹𝗼𝘀 𝗼𝗷𝗼𝘀, 𝗽𝗼𝗻𝗶𝗲́𝗻𝗱𝗼𝗻𝗼𝘀 𝗲𝗻 𝘁𝘂𝘀 𝘇𝗮𝗽𝗮𝘁𝗼𝘀, 𝘀𝗼𝗹𝘂𝗰𝗶𝗼𝗻𝗮𝗻𝗱𝗼 𝗽𝗿𝗼𝗯𝗹𝗲𝗺𝗮́𝘁𝗶𝗰𝗮𝘀 𝗲𝗻 𝗰𝗼𝗻𝗷𝘂𝗻𝘁𝗼, en equipo, demostrando que con capacidad y voluntad siempre se puede, haciendo gestión antes de ser gestión. Somos un equipo genuino realmente comprometido con Jesús María y contigo. 𝗘𝗻 𝗲𝘀𝘁𝗮 𝗲𝗹𝗲𝗰𝗰𝗶𝗼́𝗻 𝗻𝗼 𝗶𝗺𝗽𝗼𝗿𝘁𝗮 𝗾𝘂𝗶𝗲́𝗻 𝘁𝗲 𝗼𝗳𝗿𝗲𝗰𝗲 𝗺𝗮́𝘀, 𝘀𝗶𝗻𝗼, 𝗾𝘂𝗶𝗲́𝗻 𝘁𝗲 𝗴𝗮𝗿𝗮𝗻𝘁𝗶𝘇𝗮 𝗛𝗢𝗡𝗘𝗦𝗧𝗜𝗗𝗔𝗗. Nuestra gestión no será allanada ni intervenida por la fiscalía por lavado de activos, ni se robarán el bronce de nuestros monumentos como ocurrió en el pasado. 𝗤𝘂𝗲𝗿𝗶𝗱𝗼 𝘃𝗲𝗰𝗶𝗻𝗼, 𝗚𝗮𝗻𝗲́𝗺𝗼𝘀𝗹𝗲 𝗮 𝗹𝗼𝘀 𝘃𝗶𝗲𝗷𝗼𝘀 𝗰𝗼𝗿𝗿𝘂𝗽𝘁𝗼𝘀 𝗺𝗮𝗻𝗲𝗷𝗼𝘀 𝗺𝘂𝗻𝗶𝗰𝗶𝗽𝗮𝗹𝗲𝘀 𝘆 𝗲𝘃𝗶𝘁𝗲𝗺𝗼𝘀 𝗾𝘂𝗲 𝗻𝗼𝘀 𝘀𝗶𝗴𝗮𝗻 𝗺𝗲𝘁𝗶𝗲𝗻𝗱𝗼 𝗹𝗮 𝗺𝗮𝗻𝗼 𝗮𝗹 𝗯𝗼𝗹𝘀𝗶𝗹𝗹𝗼. Súmate a esta cruzada para que Jesús María esté en buenas manos. Con corazón todo sale mejor!\nAtte,\n𝗟𝘂𝗶𝘇 𝗖𝗮𝗿𝗹𝗼𝘀 𝗥𝗲𝗮́𝘁𝗲𝗴𝘂𝗶.\n𝗔𝗹𝗰𝗮𝗹𝗱𝗲 𝗱𝗲 𝗝𝗲𝘀𝘂́𝘀 𝗠𝗮𝗿𝗶́𝗮 𝟮𝟬𝟮𝟲.\n#SomosReátegui #JesúsMaría #CarlosBruce",
