                     "summary":  "Circulando fuera de servicio por el distrito de Villa El Salvador, se aprecia uno de los buses Modasa Titán 2016 que forman parte de la ruta “6” de la empresa LAPSO. Este ejemplar anteriormente formó parte de la ruta “B39” de la empresa ETERSAC.\n\nLos Laureles del Perú S.A. (LAPSO S.A.)\nRuta 1122 [La 6 / La G]: (Pachacámac - Jesús María)\n- Carrocería: Modasa Titán Urbano 2016\n- Chasis: Mercedes-Benz OF-1721/59 BlueTec 5\n- Fotografía: Víctor Hugo Azañero\n- Ubicación: Av. María Elena Moyano / Av. José Carlos Mariátegui / V.E.S. Ruta D (Villa El Salvador)\n- Fecha: 03/06/2026\n- Recorrido:\nLas Palmas (Av. Quebrada Verde / Calle S/N) - José Gálvez - Óvalo José Gálvez - Av. Pachacútec - Terminal Pesquero - Hospital María Auxiliadora - Los Héroes - Ciudad - Puente Atocongo - La Bolichera - Tomás Marsano - Óvalo Higuereta - República de Panamá - Corpac - Canaval y Moreyra - Juan de Arona / Andrés Reyes - Paseo Parodi - Prolongación Iquitos - Prolongación Iquitos / Jr. Soledad - Prolongación Iquitos / Ignacio Merino - Jr. Risso / Ignacio Merino - Francisco de Zela / Manuel Segura - Hospital del Empleado - General Felipe Salaverry - Plaza Jorge Chávez (Av. General Felipe Salaverry / Av. 28 de Julio).",
